mapper.update:
/*insertMasterCmClClosingTotal*/

		MERGE INTO KEP_SUBUL_JOJUNG A /* 수불조정 */
		USING DUAL ON 
		(
		        A.YYYYMM    = #{sel_yyyymm}
		    AND A.DEPT_CODE = #{sel_dept_code}
		    AND A.TYPE      = #{sel_type}
		)
		WHEN MATCHED THEN
		    UPDATE
		    SET J_AMT       = #{sel_j_amt}
		      , REMARK      = #{sel_remark}
		      , ADD_DATE    = TO_CHAR(SYSDATE, 'YYYYMMDD')
		      , ADD_TIME    = TO_CHAR(SYSDATE, 'HH24MISS')
		      , ADD_USER_ID = #{st_user_id}
		WHEN NOT MATCHED THEN
		    INSERT 
		    ( 
		        YYYYMM
		      , DEPT_CODE
		      , TYPE
		      , J_AMT
		      , REMARK
		      , ADD_DATE
		      , ADD_TIME
		      , ADD_USER_ID 
		    )
		    VALUES 
		    ( 
		        #{sel_yyyymm}
		      , #{sel_dept_code}
		      , #{sel_type}
		      , #{sel_j_amt}
		      , #{sel_remark}
		      , TO_CHAR(SYSDATE, 'YYYYMMDD')
		      , TO_CHAR(SYSDATE, 'HH24MISS')
		      , #{st_user_id}
		    )
